<script setup>
import { computed, onUnmounted, ref, watch } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { apiClient } from '../../utils/api.js';
import { applyKeyModel } from '../../../../src/shared/workflow-key-models.js';
import {isReviewedMold} from '../../../../src/shared/key-mold-mapping.js';
import { categoryKey, materialCoversFitments } from '../../../../src/shared/workflow-materials.js';
import WorkflowMaterialInput from './WorkflowMaterialInput.vue';
import WorkflowValuePreview from './WorkflowValuePreview.vue';
const props=defineProps({values:{type:Object,required:true},node:{type:Object,required:true},category:{type:Object,default:()=>({})},disabled:Boolean,refresh:{type:Number,default:0}}),emit=defineEmits(['upload','manage']);
const records=ref([]),error=ref(''),loading=ref(false),saving=ref(false),saveOpen=ref(false),saveMode=ref('new'),replaceId=ref(''),name=ref('');let sequence=0;
const fits=computed(()=>props.values.__fitments?.length?props.values.__fitments:props.values.model?[{brand:String(props.values.model).split(' ')[0],model:String(props.values.model).split(' ').slice(1).join(' ')}]:[]);
const selected=computed(()=>records.value.find(r=>r.id===props.values.__keyModelId));
const exact=computed(()=>records.value.filter(r=>materialCoversFitments(r,fits.value)));
async function load(){const seq=++sequence;if(!fits.value.length){records.value=[];loading.value=false;return;}loading.value=true;error.value='';try{const matches=await apiClient.get('/api/product-workflows/key-model-matches?'+new URLSearchParams({fitments:JSON.stringify(fits.value),category:categoryKey(props.category),includePending:'1'}),{noCache:true});if(seq!==sequence)return;records.value=matches;const removed=Boolean(props.values.__keyModelId&&!records.value.some(r=>r.id===props.values.__keyModelId));if(removed&&!props.disabled){props.values.key=[];delete props.values.__keyModelId;error.value='原适配资料不适用于当前选择，请重新选择';}if(!removed&&exact.value.filter(isReviewedMold).length===1&&exact.value.length===1&&!props.values.key?.some(Boolean)&&!props.disabled)applyKeyModel(props.values,exact.value[0],props.node.count);}catch(e){if(seq===sequence)error.value='适配库暂未加载，仍可手动上传';}finally{if(seq===sequence)loading.value=false;}}
onUnmounted(()=>{sequence++;});watch([()=>props.values.model,()=>props.refresh],load,{immediate:true});
async function choose(record){if(record.payload.unresolvedBindings?.length)return ElMessage.warning('这份资料还有旧型号未绑定，请先从资料库编辑并选择系统型号');if((record.payload.bindings?.length||record.payload.brand)&&!materialCoversFitments(record,fits.value))return ElMessage.warning('这份模具未覆盖全部所选型号，请核对适配范围，或按不同模具拆分产品');if(!isReviewedMold(record)){try{await ElMessageBox.confirm('请核对图片外形、按键和挂孔与当前产品一致。确认后保存系统品牌型号绑定，并启用这份资料。','确认适配资料',{confirmButtonText:'适配，选用并保存',cancelButtonText:'返回核对'});record=await apiClient.post(`/api/product-workflows/${record.kind==='key_model'?'key-models':'materials'}`,{id:record.id,revision:record.revision,payload:{...record.payload,reviewStatus:'verified'}});await load();}catch(e){if(e?.message)ElMessage.error(e.message);return;}}applyKeyModel(props.values,record,props.node.count);}
function removed(values){props.values.key=values;delete props.values.__keyModelId;}
function openSave(){name.value=selected.value?.payload.label||selected.value?.name||'钥匙模具';saveMode.value='new';replaceId.value=selected.value?.id||'';saveOpen.value=true;}
async function save(){saving.value=true;try{if(!name.value.trim())throw new Error('请填写模具名称');if(!fits.value.length)throw new Error('请先选择品牌和型号，再保存适配绑定');const images=props.values.key.filter(Boolean);if(!images.length)throw new Error('请先上传适配钥匙图片');const existing=saveMode.value==='replace'?records.value.find(r=>r.id===replaceId.value):null;if(saveMode.value==='replace'&&!existing)throw new Error('请选择要更新的原资料');if(existing?.payload.unresolvedBindings?.length)throw new Error('该资料还有旧型号未绑定，请先从资料库编辑，或选择另存为新模具');const bindings=fits.value.reduce((rows,f)=>{let b=rows.find(b=>b.brand===f.brand);if(!b){b={brand:f.brand,models:[]};rows.push(b);}b.models.push(f.model);return rows;},[]);const payload={...(existing?.payload||{}),name:name.value.trim(),images,role:'compatibility',reviewStatus:'verified',category:'钥匙模具',bindings:existing?.payload.bindings?.length?existing.payload.bindings:bindings,listingCategory:categoryKey(props.category)?{key:categoryKey(props.category),name:props.category.categoryName||props.category.name}:existing?.payload.listingCategory||null};if(existing?.kind==='key_model')Object.assign(payload,{label:name.value.trim()});const saved=await apiClient.post(`/api/product-workflows/${existing?.kind==='key_model'?'key-models':'materials'}`,{id:existing?.id,revision:existing?.revision,payload});await load();applyKeyModel(props.values,saved,props.node.count);saveOpen.value=false;ElMessage.success(existing?'原资料已更新；历史任务保留旧图':'已另存为新模具，原资料保持不变');}catch(e){ElMessage.error(e.message);}finally{saving.value=false;}}
</script>
<template><div class="key-picker"><div class="key-picker-heading"><strong>适配钥匙</strong><el-button link type="primary" :disabled="disabled" @click="emit('manage',{target:values,role:'compatibility',bindings:fits.reduce((rows,f)=>{let b=rows.find(b=>b.brand===f.brand);if(!b){b={brand:f.brand,models:[]};rows.push(b);}b.models.push(f.model);return rows;},[])})">从钥匙库选择 / 新增</el-button></div><p>{{ loading?'正在筛选适配资料…':error||(records.length?'按系统品牌型号展示全部候选；待核对资料请预览后确认，多个候选由你选择。手动上传优先。':'未匹配到模具，可直接上传；不上传则隐藏裸钥匙并跳过适配对照详情。') }}</p><div class="key-suggestions"><article v-for="record in records" :key="record.id" :class="{selected:values.__keyModelId===record.id}"><WorkflowValuePreview :value="record.payload.images" format="images"/><div><strong>{{ record.payload.label||record.name }}</strong><el-tag v-if="!isReviewedMold(record)" type="warning" size="small">{{ record.payload.unresolvedBindings?.length?'待绑定目录':'待核对候选' }}</el-tag><el-button :disabled="disabled" :type="values.__keyModelId===record.id?'primary':'default'" size="small" @click="choose(record)">{{ values.__keyModelId===record.id?'已选用':'选用此模具' }}</el-button></div><small v-if="!materialCoversFitments(record,fits)">仅覆盖部分所选型号，需核对</small></article></div><p v-if="selected">已引用：{{ selected.name }}<el-button v-if="values.__keyModelRevision!==selected.revision" link type="warning" :disabled="disabled" @click="choose(selected)">资料已更新，更新引用</el-button></p><el-alert v-if="values.key?.some(Boolean)&&!values.__keyModelId" title="这张图片仅用于本次生产，尚未存入钥匙库。需要复用时点击下方保存。" type="info" :closable="false"/><WorkflowMaterialInput :model-value="values.key" compact :node="node" :disabled="disabled" @update:model-value="removed" @upload="(file,index)=>emit('upload',file,index)"/><el-button v-if="values.key?.some(Boolean)" :disabled="disabled" link type="primary" @click="openSave">保存到企业钥匙库</el-button><el-dialog v-model="saveOpen" title="保存钥匙模具" width="600px" append-to-body :show-close="!saving" :close-on-click-modal="false"><el-form label-position="top" :disabled="saving"><el-form-item label="模具名称"><el-input v-model="name" placeholder="例如：四键菱形、三键长条"/></el-form-item><el-form-item label="保存方式"><el-radio-group v-model="saveMode"><el-radio value="new">另存为新模具（保留现有资料）</el-radio><el-radio value="replace" :disabled="!records.length">更新已有资料</el-radio></el-radio-group></el-form-item><el-form-item v-if="saveMode==='replace'" label="选择要更新的原资料"><el-select v-model="replaceId" placeholder="明确选择要替换的资料"><el-option v-for="record in records" :key="record.id" :value="record.id" :label="record.name"/></el-select><small>只更新明确选中的这一份资料；历史任务仍使用原快照。</small></el-form-item><WorkflowValuePreview :value="values.key" format="images"/></el-form><template #footer><el-button :disabled="saving" @click="saveOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{ saveMode==='replace'?'确认更新原资料':'保存为新模具' }}</el-button></template></el-dialog></div></template>
<style scoped>.key-picker{padding:14px;background:var(--el-fill-color-lighter);border-radius:8px}.key-picker-heading{display:flex;justify-content:space-between;gap:12px;align-items:center}.key-picker p{font-size:12px;line-height:1.6;color:var(--el-text-color-secondary)}.key-suggestions{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;margin-bottom:12px}.key-suggestions article{padding:10px;border:1px solid var(--el-border-color);border-radius:6px;min-width:0}.key-suggestions article.selected{border-color:var(--el-color-primary)}.key-suggestions article>div:last-of-type{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-top:8px;flex-wrap:wrap}.key-suggestions strong{font-size:12px;flex-basis:100%;line-height:1.6}.key-suggestions .el-tag{flex-shrink:0}.key-suggestions .el-button{margin-left:auto}.el-select{width:100%}.el-radio-group{display:grid;gap:8px}small{display:block;margin-top:8px;color:var(--el-text-color-secondary);line-height:1.6}</style>
